<section class="card"><div class="card-head"><div><h2><?= $edit ? 'Edit Penerimaan' : 'Catat Penerimaan Donasi' ?></h2><p class="muted">Setiap transaksi otomatis membuat atau memperbarui jurnal kas.</p></div><?php if($edit): ?><a class="btn btn-ghost" href="index.php?page=penerimaan">Batal edit</a><?php endif; ?></div>
<?php if($err): ?><div class="alert alert-err"><?=e($err)?></div><?php endif; ?>
<form method="POST" class="form-grid"><?=csrf_field()?>
<input type="hidden" name="form_action" value="<?= $edit?'update':'create' ?>"><?php if($edit): ?><input type="hidden" name="id" value="<?= (int)$edit['id']?>"><?php endif; ?>
<label>Tanggal penerimaan<input type="date" name="tanggal" value="<?=e($edit['tanggal']??$_POST['tanggal']??date('Y-m-d'))?>" required></label>
<div class="full"><label style="display:block;margin-bottom:8px">Donatur</label><label style="display:inline-flex;align-items:center;gap:8px;margin-right:18px"><input type="radio" name="donatur_mode" value="pilih" <?=((($_POST['donatur_mode']??'pilih')==='pilih'))?'checked':''?> onchange="toggleDonaturBaru()"> Pilih donatur</label><label style="display:inline-flex;align-items:center;gap:8px"><input type="radio" name="donatur_mode" value="baru" <?=((($_POST['donatur_mode']??'pilih')==='baru'))?'checked':''?> onchange="toggleDonaturBaru()"> + Donatur baru</label></div>
<div id="pilihDonatur"><label>Donatur terdaftar<select name="donatur_id" id="donatur_id"><option value="">Pilih donatur</option><?php foreach($donatur as $d):?><option value="<?=(int)$d['id']?>" <?=((($_POST['donatur_id']??$edit['donatur_id']??'')==$d['id'])?'selected':'')?>><?=e($d['nama'])?></option><?php endforeach;?></select></label></div>
<div id="formDonaturBaru" class="full" style="display:none"><div class="form-grid"><label>Nama donatur<input name="nama_donatur" maxlength="100" value="<?=e($_POST['nama_donatur']??'')?>"></label><label>Jenis<select name="jenis_donatur"><option value="individu" <?= (($_POST['jenis_donatur']??'individu')==='individu')?'selected':'' ?>>Individu</option><option value="lembaga" <?= (($_POST['jenis_donatur']??'')==='lembaga')?'selected':'' ?>>Lembaga</option></select></label><label>Telepon<input name="telepon_donatur" maxlength="20" value="<?=e($_POST['telepon_donatur']??'')?>"></label><label>Alamat<input name="alamat_donatur" maxlength="255" value="<?=e($_POST['alamat_donatur']??'')?>"></label></div></div>
<label>Kategori dana<select name="kategori_id" required><option value="">Pilih kategori</option><?php foreach($kategori as $k):?><option value="<?=(int)$k['id']?>" <?=((($_POST['kategori_id']??$edit['kategori_id']??'')==$k['id'])?'selected':'')?>><?=e($k['nama'])?> — <?=e(JurnalKas::POS[$k['pos_dana']]??$k['pos_dana'])?></option><?php endforeach;?></select></label>
<label>Nominal (Rp)<input type="number" name="nominal" min="1" step="1" value="<?=e($_POST['nominal']??$edit['nominal']??'')?>" required></label><label class="full">Keterangan<input name="keterangan" maxlength="255" value="<?=e($_POST['keterangan']??$edit['keterangan']??'')?>"></label>
<div class="full"><button class="btn btn-primary" type="submit"><?= $edit?'Simpan Perubahan':'Simpan Penerimaan + Jurnal' ?></button></div></form>
<script>function toggleDonaturBaru(){const baru=document.querySelector('input[name="donatur_mode"]:checked')?.value==='baru';document.getElementById('formDonaturBaru').style.display=baru?'block':'none';document.getElementById('pilihDonatur').style.display=baru?'none':'block';document.getElementById('donatur_id').required=!baru;document.querySelector('input[name="nama_donatur"]').required=baru;}toggleDonaturBaru();</script></section>
<section class="card"><h2>Riwayat Penerimaan</h2><div class="table-wrap"><table><thead><tr><th>No Kuitansi</th><th>Tanggal</th><th>Donatur</th><th>Kategori</th><th>Pos Dana</th><th>Nominal</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="7" class="empty">Belum ada penerimaan.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['no_kuitansi'])?></td><td><?=e(tgl($r['tanggal']))?></td><td><?=e($r['donatur'])?></td><td><?=e($r['kategori'])?></td><td><?=e(JurnalKas::POS[$r['pos_dana']]??$r['pos_dana'])?></td><td class="num"><?=rupiah($r['nominal'])?></td><td class="actions"><a class="btn btn-sm btn-warn" href="index.php?page=penerimaan&action=edit&id=<?=(int)$r['id']?>">Edit</a> <a class="btn btn-sm btn-primary" target="_blank" href="index.php?page=penerimaan&action=kuitansi&id=<?=(int)$r['id']?>">Cetak Kuitansi</a><form method="POST" data-confirm="Hapus penerimaan dan jurnal terkait?"><?=csrf_field()?><input type="hidden" name="form_action" value="delete"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="btn btn-sm btn-danger">Hapus</button></form></td></tr><?php endforeach;endif;?></tbody></table></div></section>
